ctx.shadowColor='#6aeaff';ctx.shadowBlur=18;ctx.fillStyle='#74eaff';roundRect(paddle.x,paddle.y,paddle.w,paddle.h,8);ctx.fill();ctx.shadowBlur=0;let rg=ctx.createRadialGradient(ball.x-3,ball.y-3,1,ball.x,ball.y,ball.r*1.8);rg.addColorStop(0,'#fff');rg.addColorStop(.4,'#b8f9ff');rg.addColorStop(1,'#58bfff');ctx.fillStyle=rg;ctx.shadowColor='#75efff';ctx.shadowBlur=22;ctx.beginPath();ctx.arc(ball.x,ball.y,ball.r,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;for(const d of drops){ctx.fillStyle='#ffe27a';ctx.shadowColor='#ffe27a';ctx.shadowBlur=16;ctx.beginPath();ctx.arc(d.x,d.y,10,0,Math.PI*2);ctx.fill();ctx.fillStyle='#17152b';ctx.font='bold 12px system-ui';ctx.textAlign='center';ctx.fillText('+',d.x,d.y+4);ctx.shadowBlur=0}for(const p of particles){ctx.globalAlpha=p.life;ctx.fillStyle=p.color;ctx.fillRect(p.x,p.y,3,3)}ctx.globalAlpha=1}
